    const sinEtiqueta = v => String(v ?? '').replace(/^\s*(?:C\.?\s?I\.?\s?F|N\.?\s?I\.?\s?F(?:-IVA)?|D\.?\s?N\.?\s?I|VAT)\s*[:.\-]?\s*/i, '');
    const excluidos = [...Object.values(CIF_GRUPO), normCif(parsed.cabecera.cliente_cif)];
    const candidatos = [...new Set((Array.isArray(parsed.identificadores_fiscales) ? parsed.identificadores_fiscales : []).map(v => normCif(sinEtiqueta(v))))]
      .filter(c => c.length >= 8 && /\d/.test(c) && !excluidos.includes(c));
    if (candidatos.length === 1) {
      parsed.cabecera.emisor_cif = candidatos[0];
      avisoCif = 'CIF del emisor tomado de los identificadores fiscales del documento (' + candidatos[0] + ')';
    }
  }
  // Facturas que solo traen importes con IVA incluido (sin base ni importe de IVA): Gemini a veces no las desglosa.
  // Se desglosa con el tipo que indique la propia factura o, si no figura, con el de la última factura anterior del mismo proveedor en el sheet.
  let avisoIvaIncluido = '';
  const cabIva = parsed.cabecera;
  if (cabIva && typeof cabIva.total_factura === 'number' && Number.isFinite(cabIva.total_factura) && !(Number(cabIva.total_base) > 0) && !(Number(cabIva.total_iva_importe) > 0)) {
    let pctIncl = aNumero(cabIva.total_iva_porcentaje);
    let origenIva = 'el que indica la propia factura';
    if (pctIncl === undefined) {
      const cifProv = normCif(cabIva.emisor_cif);
      let ultima = null;
      try {
        if (cifProv) for (const fila of $('Facturas anteriores').all()) {
          const f = fila.json;
          const pct = aNumero(f.total_iva_porcentaje);
          if (normCif(f.emisor_cif) !== cifProv || ![0, 4, 5, 10, 21].includes(pct) || !(aNumero(f.total_base) > 0) || String(f.Estado ?? '').trim() === 'Error') continue;
          if (!ultima || Number(f.row_number) >= Number(ultima.row_number)) ultima = { pct, row_number: f.row_number, numero: String(f.numero_factura ?? '').replace(/^'/, '') };
        }
      } catch (e) { /* el sheet no se ha podido leer: se sigue sin tipo */ }
      if (ultima) { pctIncl = ultima.pct; origenIva = 'el de la última factura del proveedor (' + ultima.numero + ')'; }
    }
    if (pctIncl === undefined) {
      avisoIvaIncluido = 'La factura no trae base ni IVA y no hay una factura anterior del proveedor de la que tomar el tipo: base e IVA sin calcular (revisar)';
    } else {
      const cent = n => Math.round((n + Number.EPSILON) * 100) / 100;
      const vacio = v => v === null || v === undefined || v === '';
      const divisor = 1 + pctIncl / 100;
      cabIva.total_base = cent(cabIva.total_factura / divisor);
      cabIva.total_iva_porcentaje = pctIncl;
      cabIva.total_iva_importe = cent(cabIva.total_factura - cabIva.total_base);
      for (const l of parsed.lineas || []) {
        const tot = aNumero(l.importe_linea_total);
        if (tot === undefined || !vacio(l.importe_linea_sin_iva)) continue;
        const sin = cent(tot / divisor);
        l.importe_linea_sin_iva = sin;
        if (vacio(l.precio_unitario)) l.precio_unitario = Number(l.cantidad) > 0 ? cent(sin / Number(l.cantidad)) : sin;
        l.iva_porcentaje = pctIncl;
        l.iva_importe = cent(tot - sin);
      }
      avisoIvaIncluido = 'La factura solo trae importes con IVA incluido: base e IVA calculados con ' + origenIva + ', ' + pctIncl + '%';
    }
  }
  const numeroFactura = parsed.cabecera?.numero_factura?.toString();

  // Red de seguridad por si el agente no devuelve el array de líneas
  const lineasArray = (parsed.lineas || []).map(linea => {
    const l = { ...linea };
    for (const campo of camposLinea) {
      if (campo in l) l[campo] = aNumero(l[campo]) ?? l[campo];
    }
    return l;
  });

  // Líneas sin IVA (la factura lo aplica de forma global al final): se reparte el porcentaje de la cabecera
  const r2 = n => Math.round((n + Number.EPSILON) * 100) / 100;
  const pctCab = aNumero(parsed.cabecera?.total_iva_porcentaje);
  let avisoImportes = '';
  // Gemini a veces "reajusta" los importes de línea en vez de copiarlos (p. ej. 3 x 2,80 = 8,40 y devuelve 8,11).
  // Si cantidad x precio (menos el descuento) recompone la base imponible de la factura y los importes leídos no, se usan los recalculados.
  let avisoCorreccion = '';
  const baseCab = parsed.cabecera?.total_base;
  if (lineasArray.length && typeof baseCab === 'number' && Number.isFinite(baseCab)) {
    const tolSuma = Math.max(0.05, 0.005 * lineasArray.length) + 0.005;
    const recalculado = l => {
      const cant = Number(l.cantidad), precio = Number(l.precio_unitario), dto = Number(l.descuento_porcentaje) || 0;
      if (!(cant > 0) || !(precio > 0) || !Number.isFinite(Number(l.importe_linea_sin_iva))) return null;
      const esperado = r2(cant * precio * (1 - dto / 100));
      return Math.abs(esperado - Number(l.importe_linea_sin_iva)) > 0.02 ? esperado : null;
    };
    const sumaLeida = r2(lineasArray.reduce((a, l) => a + (Number(l.importe_linea_sin_iva) || 0), 0));
    const sumaRecalc = r2(lineasArray.reduce((a, l) => a + (recalculado(l) ?? (Number(l.importe_linea_sin_iva) || 0)), 0));
    if (Math.abs(sumaLeida - baseCab) > tolSuma && Math.abs(sumaRecalc - baseCab) <= tolSuma) {
      const corregidas = [];
      for (const l of lineasArray) {
        const esperado = recalculado(l);
        if (esperado === null) continue;
        corregidas.push(l.numero_linea);
        l.importe_linea_sin_iva = esperado;
        const pct = Number(l.iva_porcentaje);
        if (pct > 0) l.iva_importe = r2(esperado * pct / 100);
        l.importe_linea_total = r2(esperado + (Number(l.iva_importe) || 0));
      }
      avisoCorreccion = 'Importes de línea corregidos (cantidad x precio) en las líneas ' + corregidas.join(', ') + ': los leídos sumaban ' + sumaLeida.toFixed(2) + ' y la base imponible es ' + baseCab.toFixed(2);
    }
  }
  if (lineasArray.length && pctCab > 0 && lineasArray.every(l => !(Number(l.iva_porcentaje) > 0) && !(Number(l.iva_importe) > 0))) {
    for (const l of lineasArray) if (Number.isFinite(Number(l.importe_linea_sin_iva))) l.iva_porcentaje = pctCab;
    avisoImportes = 'Las líneas venían sin IVA: se ha aplicado el ' + pctCab + '% de la factura a cada línea';
  }
  // Línea con porcentaje de IVA pero sin importe de IVA o con el total sin IVA: se recalcula
  for (const l of lineasArray) {
    const base = Number(l.importe_linea_sin_iva), pct = Number(l.iva_porcentaje);
    if (l.importe_linea_sin_iva !== null && Number.isFinite(base) && pct > 0 && !(Number(l.iva_importe) > 0)) {
      l.iva_importe = r2(base * pct / 100);
      l.importe_linea_total = r2(base + l.iva_importe);
    }
  }
  // La suma de las líneas tiene que dar el total de la factura (más la retención, si hay)
  const totalCab = parsed.cabecera?.total_factura;
  if (lineasArray.length && typeof totalCab === 'number' && Number.isFinite(totalCab)) {
    const suma = r2(lineasArray.reduce((a, l) => a + (Number(l.importe_linea_total) || 0), 0));
    const esperado = r2(totalCab + (Number(parsed.cabecera.total_irpf_importe) || 0));
    if (Math.abs(suma - esperado) > Math.max(0.05, 0.005 * lineasArray.length) + 0.005) {
      avisoImportes += (avisoImportes ? ' | ' : '') + 'Importes que no cuadran: las líneas suman ' + suma.toFixed(2) + ' y el total de la factura es ' + esperado.toFixed(2) + ' (revisar las líneas antes de aprobar)';
    }
  }

  return [{
    json: {
      cabecera: {
        ...parsed.cabecera,
        numero_factura: numeroFactura
      },
      lineas: lineasArray,
      total_lineas: lineasArray.length,
      aviso_grupo: avisoGrupo,
      incoherencia_grupo: incoherenciaGrupo,
      aviso_importes: [avisoLineas, avisoCif, avisoIvaIncluido, avisoCorreccion, avisoImportes].filter(Boolean).join(' | '),
      pdf_base64: $('Buscamos en Proceso').first().json.pdf_base64,
      id_proceso: $('Buscamos en Proceso').first().json.id_proceso.trim(),
      email_origen: $('Buscamos en Proceso').first().json.email_origen,
      nombre_remitente: $('Buscamos en Proceso').first().json.nombre_remitente,
      nombre_archivo: $('Buscamos en Proceso').first().json.nombre_archivo,
      fecha_recepcion: $('Buscamos en Proceso').first().json.fecha_recepcion,
      hora_recepcion: $('Buscamos en Proceso').first().json.hora_recepcion,
      asunto_email: $('Buscamos en Proceso').first().json.asunto_email
    }
  }];
} catch(e) {
  return [{
    json: {
      error: 'JSON malformado: ' + e.message,
      raw_length: $('Agente extractor Vertex AI').first().json.candidates?.[0]?.content?.parts?.[0]?.text?.length || 0,
      id_proceso: $('Buscamos en Proceso').first().json.id_proceso,
      nombre_archivo: $('Buscamos en Proceso').first().json.nombre_archivo,
      email_origen: $('Buscamos en Proceso').first().json.email_origen
    }
  }];
}

const idProceso = $('Inserta Cabecera').first().json.id_proceso;
const rowsToDelete = [];

for (const [index, item] of Object.entries(items)) {
  if (item.json.id_proceso_lineas === idProceso) {
    // Google Sheets row numbers empiezan en 2 porque la fila 1 suele ser el encabezado
    rowsToDelete.push(item.json.row_number);

  }
}

if (rowsToDelete.length === 0) {
  // Devuelve un item con rowNumber 0 (no válido)
  return [{ json: { rowNumber: 0 } }];
}

// Ordenar filas de mayor a menor para borrar sin desfasar índices
rowsToDelete.sort((a, b) => b - a);

return rowsToDelete.map(row => ({ json: { rowNumber: row } }));
